def optimize(available, ops):
    available = set(available)
    provenance = {}
    needed = set()
    pushed = []
    kept = []

    def resolve(name):
        if name in provenance:
            return set(provenance[name])
        if name in available:
            return {name}
        raise ValueError(f"unknown column {name!r}")

    derived = set()
    for op in ops:
        kind = op["op"]
        if kind == "filter":
            column = op["column"]
            needed |= resolve(column)
            if column in available and column not in derived:
                pushed.append(op)
            else:
                kept.append(op)
        elif kind == "with_columns":
            sources = set()
            for name in op["inputs"]:
                sources |= resolve(name)
            provenance[op["output"]] = sources
            derived.add(op["output"])
            needed |= sources
            kept.append(op)
        elif kind == "select":
            for name in op["columns"]:
                needed |= resolve(name)
            kept.append(op)
        elif kind == "group_by":
            for name in op["keys"]:
                needed |= resolve(name)
            for name in op["aggs"].values():
                needed |= resolve(name)
            kept.append(op)
        else:
            raise ValueError(f"unknown operation {kind!r}")

    return {
        "scan_columns": sorted(needed & available),
        "pushed_filters": pushed,
        "kept": kept,
    }
